// ─── Staff notify ────────────────────────────────────────────────────────────

type TeamAdminRecipient = {
  id: number;
  email: string;
  first_name: string;
  last_name: string;
  phone: string | null;
  preferred_language: string | null;
  prefs: AdminNotificationPrefs;
  role?: AdminRole;
};

/** Keep in sync with client/lib/adminNotifyPrefs.ts ADMIN_NOTIFY_EVENT_KEYS. */
const ADMIN_NOTIFY_EVENT_KEYS: AdminNotifyEventKey[] = [
  "lead_submitted",
  "get_credit_report_lead",
  "contact_submitted",
  "partner_referral",
  "affiliate_signup",
  "affiliate_client_registered",
  "client_signup",
  "client_signup_reminder",
  "contractor_signup",
  "contractor_signup_reminder",
  "contractor_application_submitted",
  "contractor_compliance_alert",
  "affiliate_onboarding",
  "line_needs_owner",
  "duplicate_blocked",
  "draw_submitted",
  "lead_converted",
  "client_created",
  "milestone_changed",
  "commission_accrued",
  "contract_sent",
  "inbound_sms",
  "inbound_email",
];

const ADMIN_NOTIFY_EVENT_KEY_SET = new Set<string>(ADMIN_NOTIFY_EVENT_KEYS);

function allAdminNotifyEventsOn(): AdminNotifyEventToggles {
  const out = {} as AdminNotifyEventToggles;
  for (const key of ADMIN_NOTIFY_EVENT_KEYS) out[key] = true;
  return out;
}

function defaultAdminNotificationPrefs(): AdminNotificationPrefs {
  const all = allAdminNotifyEventsOn();
  return {
    email: { ...all },
    in_app: { ...all },
    sms: { ...all },
  };
}

function mergeAdminNotifyChannel(
  raw: unknown,
  defaults: AdminNotifyEventToggles,
): AdminNotifyEventToggles {
  const out = { ...defaults };
  if (!raw || typeof raw !== "object") return out;
  const obj = raw as Record<string, unknown>;
  for (const key of ADMIN_NOTIFY_EVENT_KEYS) {
    if (typeof obj[key] === "boolean") out[key] = obj[key] as boolean;
  }
  return out;
}

function parseAdminNotificationPrefs(raw: unknown): AdminNotificationPrefs {
  const defaults = defaultAdminNotificationPrefs();
  if (!raw) return defaults;
  let parsed: unknown = raw;
  if (typeof raw === "string") {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return defaults;
    }
  }
  if (!parsed || typeof parsed !== "object") return defaults;
  const obj = parsed as Record<string, unknown>;
  return {
    email: mergeAdminNotifyChannel(obj.email, defaults.email),
    in_app: mergeAdminNotifyChannel(obj.in_app, defaults.in_app),
    sms: mergeAdminNotifyChannel(obj.sms, defaults.sms),
  };
}

function adminNotifyPrefOn(
  prefs: AdminNotificationPrefs,
  channel: AdminNotifyChannel,
  eventKey: AdminNotifyEventKey,
): boolean {
  return prefs[channel][eventKey] !== false;
}

function isTwilioNotifyConfigured(): boolean {
  // Vitest dry-runs SMS; treat Twilio as configured so channel meta + prefs match delivery.
  if (process.env.VITEST === "true") return true;
  return !!(
    String(process.env.TWILIO_ACCOUNT_SID || "").trim() &&
    String(process.env.TWILIO_AUTH_TOKEN || "").trim()
  );
}

async function adminSmsChannelAvailable(adminId: number): Promise<boolean> {
  if (!isTwilioNotifyConfigured()) return false;
  return (await listAssignedPhoneNumbers(adminId)).length > 0;
}

async function adminNotifyChannelMetaForAdmin(adminId: number) {
  const twilioOk = isTwilioNotifyConfigured();
  const hasNumber = twilioOk
    ? (await listAssignedPhoneNumbers(adminId)).length > 0
    : false;
  const smsOk = twilioOk && hasNumber;
  return {
    email: { available: true as const, disabled_reason: null as string | null },
    in_app: {
      available: true as const,
      disabled_reason: null as string | null,
    },
    sms: {
      available: smsOk,
      disabled_reason: smsOk
        ? null
        : !twilioOk
          ? "sms_twilio_not_configured"
          : "sms_ofg_number_required",
    },
  };
}

async function insertAdminInAppNotification(opts: {
  adminId: number;
  /** scorecard_alert: super admins only, sent straight from the scorecard engine (not routed). */
  eventKey: AdminNotifyEventKey | "scorecard_alert";
  title: string;
  body?: string | null;
  linkUrl?: string | null;
  payload?: Record<string, unknown>;
  /** Recipient email when the caller already has it (skips the sandbox lookup). */
  adminEmail?: string | null;
}): Promise<number | null> {
  try {
    // Sandbox (Vitest / NOTIFY_SANDBOX): never write bell rows for real staff,
    // whichever path called (team fan-out, inbound SMS assignee, …).
    if (notifySandbox()) {
      let email = opts.adminEmail;
      if (email === undefined) {
        const [[a]] = (await pool.query<RowDataPacket[]>(
          `SELECT email FROM admins WHERE id = ? LIMIT 1`,
          [opts.adminId],
        )) as unknown as [RowDataPacket[]];
        email = a?.email ?? null;
      }
      if (!isSandboxSafeEmail(email)) return null;
    }
    const [ins] = await pool.query<ResultSetHeader>(
      `INSERT INTO admin_notifications
         (admin_id, event_key, title, body, link_url, payload_json)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [
        opts.adminId,
        opts.eventKey,
        String(opts.title || "").slice(0, 255),
        opts.body || null,
        opts.linkUrl || null,
        opts.payload ? JSON.stringify(opts.payload) : null,
      ],
    );
    return ins.insertId ? Number(ins.insertId) : null;
  } catch (e: any) {
    console.error(`[notify:in_app] admin ${opts.adminId}:`, e?.message ?? e);
    return null;
  }
}

async function listActiveTeamAdmins(): Promise<TeamAdminRecipient[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, last_name, phone, preferred_language, notification_prefs_json, role
     FROM admins
     WHERE status = 'active'
       AND role IN ('super_admin', 'admin', 'agent', 'finance', 'content')
       AND email IS NOT NULL AND TRIM(email) <> ''`,
  );
  return rows.map((r) => ({
    id: Number(r.id),
    email: String(r.email),
    first_name: String(r.first_name || "Admin"),
    last_name: String(r.last_name || ""),
    phone: r.phone ? String(r.phone) : null,
    preferred_language: (r.preferred_language as string) || "en",
    prefs: parseAdminNotificationPrefs(r.notification_prefs_json),
    role: String(r.role) as AdminRole,
  }));
}

// ── Notification routing: who gets which area (Settings → Team notifications) ──

type NotifyArea = "leads" | "clients" | "contractors" | "affiliates" | "projects" | "system";
const NOTIFY_AREAS: NotifyArea[] = ["leads", "clients", "contractors", "affiliates", "projects", "system"];
/** Event → area. inbound_sms / inbound_email are personal (line / mailbox owner) and never routed. */
const NOTIFY_EVENT_AREA: Partial<Record<AdminNotifyEventKey, NotifyArea>> = {
  lead_submitted: "leads",
  get_credit_report_lead: "leads",
  contact_submitted: "leads",
  lead_converted: "leads",
  client_signup: "clients",
  client_signup_reminder: "clients",
  client_created: "clients",
  affiliate_client_registered: "clients",
  contractor_signup: "contractors",
  contractor_signup_reminder: "contractors",
  contractor_application_submitted: "contractors",
  contractor_compliance_alert: "contractors",
  affiliate_signup: "affiliates",
  affiliate_onboarding: "affiliates",
  partner_referral: "affiliates",
  milestone_changed: "projects",
  draw_submitted: "projects",
  commission_accrued: "projects",
  contract_sent: "projects",
  line_needs_owner: "system",
  duplicate_blocked: "system",
};

/** Records a notice is about: their assigned staff member also gets it (when the area allows). */
type NotifyRefs = { clientId?: number | null; projectPublicId?: string | null };

/** Tests never write the shared routing table: they inject rules here instead. */
let notifyRoutingOverride: Map<NotifyArea, { adminIds: number[]; includeOwner: boolean }> | null = null;
export function __testSetNotifyRouting(rules: Partial<Record<NotifyArea, { adminIds: number[]; includeOwner: boolean }>> | null): void {
  notifyRoutingOverride = rules ? new Map(Object.entries(rules) as Array<[NotifyArea, { adminIds: number[]; includeOwner: boolean }]>) : null;
}

async function loadNotifyRouting(): Promise<Map<NotifyArea, { adminIds: number[]; includeOwner: boolean }>> {
  if (notifyRoutingOverride) return notifyRoutingOverride;
  // Shared DB: tests never read the live routing staff set up (default = super admins only).
  if (process.env.VITEST) return new Map();
  const [rows] = await pool.query<RowDataPacket[]>(`SELECT area, admin_ids_json, include_owner FROM notify_routing`);
  const out = new Map<NotifyArea, { adminIds: number[]; includeOwner: boolean }>();
  for (const r of rows) {
    const ids = (parseJsonCol(r.admin_ids_json) as unknown[]).map(Number).filter((n) => Number.isInteger(n) && n > 0);
    out.set(String(r.area) as NotifyArea, { adminIds: ids, includeOwner: Number(r.include_owner) === 1 });
  }
  return out;
}

async function notifyRecordOwners(refs: NotifyRefs | undefined): Promise<number[]> {
  if (!refs) return [];
  const ids = new Set<number>();
  if (refs.clientId) {
    const [[c]] = (await pool.query<RowDataPacket[]>(`SELECT assigned_admin_id FROM clients WHERE id = ?`, [refs.clientId])) as unknown as [RowDataPacket[]];
    if (c?.assigned_admin_id) ids.add(Number(c.assigned_admin_id));
  }
  if (refs.projectPublicId) {
    const [[p]] = (await pool.query<RowDataPacket[]>(
      `SELECT p.assigned_admin_id, c.assigned_admin_id AS client_owner FROM projects p LEFT JOIN clients c ON c.id = p.client_id WHERE p.public_id = ?`,
      [refs.projectPublicId],
    )) as unknown as [RowDataPacket[]];
    if (p?.assigned_admin_id) ids.add(Number(p.assigned_admin_id));
    if (p?.client_owner) ids.add(Number(p.client_owner));
  }
  return [...ids];
}

/** Test hook: recipient ids for an event (routing + record owners), before personal prefs. */
export async function __testNotifyRecipients(eventKey: AdminNotifyEventKey, refs?: NotifyRefs): Promise<number[]> {
  return (await notifyRecipientsFor(eventKey, await listActiveTeamAdmins(), refs)).map((a) => a.id);
}

/** Who gets this event: the area's chosen staff (super admins when the area isn't set up) + record owners. */
async function notifyRecipientsFor(
  eventKey: AdminNotifyEventKey,
  admins: TeamAdminRecipient[],
  refs?: NotifyRefs,
): Promise<TeamAdminRecipient[]> {
  const area = NOTIFY_EVENT_AREA[eventKey];
  if (!area) return admins;
  const rule = (await loadNotifyRouting()).get(area);
  const wanted = new Set<number>(rule ? rule.adminIds : admins.filter((a) => a.role === "super_admin").map((a) => a.id));
  if (!rule || rule.includeOwner) for (const id of await notifyRecordOwners(refs)) wanted.add(id);
  return admins.filter((a) => wanted.has(a.id));
}

/** null = all events; else selected keys. Invalid JSON → all (legacy). */
function parseNotifyExtraEvents(raw: unknown): AdminNotifyEventKey[] | null {
  if (raw == null || raw === "") return null;
  let parsed: unknown = raw;
  if (typeof raw === "string") {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!Array.isArray(parsed)) return null;
  return parsed
    .map((x) => String(x))
    .filter((k): k is AdminNotifyEventKey => ADMIN_NOTIFY_EVENT_KEY_SET.has(k));
}

/** undefined = omit; null = all; [] = none; else selected keys. */
function normalizeNotifyExtraEventsInput(
  raw: unknown,
): AdminNotifyEventKey[] | null | undefined {
  if (raw === undefined) return undefined;
  if (raw === null) return null;
  if (!Array.isArray(raw)) return undefined;
  return parseNotifyExtraEvents(raw) ?? [];
}

function notifyExtraAllowsEvent(
  events: AdminNotifyEventKey[] | null,
  eventKey: AdminNotifyEventKey,
): boolean {
  if (events == null) return true;
  return events.includes(eventKey);
}

function mapNotifyExtraEmailRow(r: RowDataPacket) {
  return {
    id: Number(r.id),
    email: String(r.email),
    label: r.label == null ? null : String(r.label),
    is_active: Number(r.is_active) === 1,
    events: parseNotifyExtraEvents(r.events_json),
    created_at: r.created_at,
  };
}

async function listExtraNotifyEmails(
  eventKey: AdminNotifyEventKey,
): Promise<string[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT email, events_json FROM admin_notify_extra_emails
     WHERE is_active = 1 AND email IS NOT NULL AND TRIM(email) <> ''`,
  );
  const out: string[] = [];
  for (const r of rows) {
    const email = String(r.email).trim().toLowerCase();
    if (!email) continue;
    if (
      notifyExtraAllowsEvent(parseNotifyExtraEvents(r.events_json), eventKey)
    ) {
      out.push(email);
    }
  }
  return out;
}

async function deliverAdminNotificationChannels(opts: {
  admin: TeamAdminRecipient;
  eventKey: AdminNotifyEventKey;
  tpl: {
    subject: string;
    html: string;
    linkUrl?: string | null;
    smsBody?: string | null;
    inAppBody?: string | null;
  };
}): Promise<{ email: boolean; in_app: boolean; sms: boolean }> {
  const { admin, eventKey, tpl } = opts;
  const result = { email: false, in_app: false, sms: false };
  const linkUrl = tpl.linkUrl || "/admin";

  if (adminNotifyPrefOn(admin.prefs, "email", eventKey)) {
    try {
      const sent = await sendEmail({
        to: admin.email,
        subject: tpl.subject,
        html: tpl.html,
      });
      if (sent.ok) result.email = true;
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:email] ${admin.email}:`,
        e?.message ?? e,
      );
    }
  }

  if (adminNotifyPrefOn(admin.prefs, "in_app", eventKey) && admin.id > 0) {
    const notifId = await insertAdminInAppNotification({
      adminId: admin.id,
      adminEmail: admin.email,
      eventKey,
      title: tpl.subject,
      body: tpl.inAppBody || null,
      linkUrl,
    });
    if (notifId) {
      result.in_app = true;
      await publishAdminBellRealtime(admin.id, {
        notification_id: notifId,
        event_key: eventKey,
      });
    }
  }

  if (
    adminNotifyPrefOn(admin.prefs, "sms", eventKey) &&
    admin.phone &&
    admin.id > 0
  ) {
    try {
      const from = await resolveAssignedSmsFrom(admin.id);
      if (from) {
        const toDigits = normalizePhoneDigits(admin.phone);
        const fromDigits = normalizePhoneDigits(from);
        if (!(toDigits && fromDigits && toDigits === fromDigits)) {
          const smsText = String(
            tpl.smsBody ||
              `${tpl.subject}${tpl.inAppBody ? `: ${tpl.inAppBody}` : ""}`,
          ).slice(0, 320);
          await sendSms({ manual: true, to: admin.phone, body: smsText, from });
          result.sms = true;
        }
      }
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:sms] admin ${admin.id}:`,
        e?.message ?? e,
      );
    }
  }

  return result;
}

async function notifyAllTeamAdmins(
  eventKey: AdminNotifyEventKey,
  build: (admin: TeamAdminRecipient) => {
    subject: string;
    html: string;
    linkUrl?: string | null;
    smsBody?: string | null;
    inAppBody?: string | null;
  },
  refs?: NotifyRefs,
): Promise<number> {
  // Routed by area (+ record owner); sandbox never notifies (or writes in-app rows for) real staff.
  const admins = (await notifyRecipientsFor(eventKey, await listActiveTeamAdmins(), refs)).filter(
    (a) => !notifySandbox() || isSandboxSafeEmail(a.email),
  );
  let sent = 0;
  let sampleTpl: {
    subject: string;
    html: string;
    linkUrl?: string | null;
  } | null = null;
  await Promise.all(
    admins.map(async (admin) => {
      try {
        const tpl = build(admin);
        if (!sampleTpl) {
          sampleTpl = {
            subject: tpl.subject,
            html: tpl.html,
            linkUrl: tpl.linkUrl,
          };
        }
        const delivered = await deliverAdminNotificationChannels({
          admin,
          eventKey,
          tpl,
        });
        if (delivered.email || delivered.in_app || delivered.sms) sent += 1;
      } catch (e: any) {
        console.error(`[notify:admin] ${admin.email}:`, e?.message ?? e);
      }
    }),
  );

  const extras = await listExtraNotifyEmails(eventKey);
  const adminEmails = new Set(admins.map((a) => a.email.toLowerCase()));
  await Promise.all(
    extras
      .filter((e) => !adminEmails.has(e))
      .filter((e) => !notifySandbox() || isSandboxSafeEmail(e))
      .map(async (email) => {
        try {
          const tpl =
            sampleTpl ||
            build({
              id: 0,
              email,
              first_name: "Team",
              last_name: "",
              phone: null,
              preferred_language: "en",
              prefs: defaultAdminNotificationPrefs(),
            });
          const result = await sendEmail({
            to: email,
            subject: tpl.subject,
            html: tpl.html,
          });
          if (result.ok) sent += 1;
        } catch (e: any) {
          console.error(`[notify:extra] ${email}:`, e?.message ?? e);
        }
      }),
  );
  return sent;
}

// ─── Validation helpers ──────────────────────────────────────────────────────

function normalizeEmail(value: unknown): string {
  return String(value || "")
    .trim()
    .toLowerCase()
    .slice(0, 255);
}

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function parseLeadBody(body: any):
  | {
      ok: true;
      data: SubmitLeadRequest;
    }
  | { ok: false; error: string } {
  const full_name = String(body?.full_name || body?.name || "").trim();
  const email = normalizeEmail(body?.email);
  const phone = String(body?.phone || "").trim();
  const property_address = String(
    body?.property_address || body?.address || "",
  ).trim();
  const soft_pull_consent = Boolean(
    body?.soft_pull_consent === true ||
    body?.soft_pull_consent === 1 ||
    body?.soft_pull_consent === "1" ||
    body?.consent === true ||
    body?.consent === "on",
  );
  const sms_marketing_consent = Boolean(
    body?.sms_marketing_consent === true ||
    body?.sms_marketing_consent === 1 ||
    body?.sms_marketing_consent === "1",
  );
  const mode: LeadMode =
    body?.mode === "event" || body?.mode === "standard"
      ? body.mode
      : "standard";
  const event_city = body?.event_city
    ? String(body.event_city).trim().slice(0, 100)
    : null;
  const eventIdNum = Number(body?.event_id);
  const event_id =
    mode === "event" && Number.isInteger(eventIdNum) && eventIdNum > 0
      ? eventIdNum
      : null;
  const source = body?.source ? String(body.source).trim().slice(0, 100) : null;
  const preferred_language =
    body?.preferred_language === "es" || body?.text_language === "es"
      ? ("es" as const)
      : ("en" as const);

  if (!full_name || full_name.length < 2) {
    return { ok: false, error: "validation.nameRequired" };
  }
  if (!isValidEmail(email)) {
    return { ok: false, error: "validation.emailInvalid" };
  }
  if (!phone || phone.replace(/\D/g, "").length < 10) {
    return { ok: false, error: "validation.phoneMin" };
  }
  if (!property_address || property_address.length < 5) {
    return { ok: false, error: "validation.addressRequired" };
  }
  // Inquiries and event RSVPs never require a credit pull (the free report is its own page).
  if (mode === "event" && event_id == null) {
    return { ok: false, error: "validation.invalidField" };
  }

  return {
    ok: true,
    data: {
      full_name: full_name.slice(0, 200),
      email: email.slice(0, 255),
      phone: phone.slice(0, 40),
      property_address: property_address.slice(0, 500),
      soft_pull_consent,
      sms_marketing_consent,
      preferred_language,
      mode,
      event_city,
      event_id,
      source,
    },
  };
}

function parseGetCreditReportBody(
  body: any,
):
  | { ok: true; data: SubmitGetCreditReportLeadRequest }
  | { ok: false; error: string } {
  const first_name = String(body?.first_name || "").trim();
  const last_name = String(body?.last_name || "").trim();
  const email = normalizeEmail(body?.email);
  const phone = String(body?.phone || "").trim();
  const preferred_language =
    body?.preferred_language === "es" || body?.text_language === "es"
      ? ("es" as const)
      : ("en" as const);
  const notes = body?.notes ? String(body.notes).trim().slice(0, 2000) : null;
  const soft_pull_consent = Boolean(
    body?.soft_pull_consent === true ||
    body?.soft_pull_consent === 1 ||
    body?.soft_pull_consent === "1" ||
    body?.consent === true,
  );

  if (!first_name || first_name.length < 1) {
    return { ok: false, error: "validation.firstNameRequired" };
  }
  if (!last_name || last_name.length < 1) {
    return { ok: false, error: "validation.lastNameRequired" };
  }
  if (!isValidEmail(email)) {
    return { ok: false, error: "validation.emailInvalid" };
  }
  if (!phone || phone.replace(/\D/g, "").length < 10) {
    return { ok: false, error: "validation.phoneMin" };
  }
  if (!soft_pull_consent) {
    return { ok: false, error: "validation.consent" };
  }

  return {
    ok: true,
    data: {
      first_name: first_name.slice(0, 100),
      last_name: last_name.slice(0, 100),
      email: email.slice(0, 255),
      phone: phone.slice(0, 40),
      preferred_language,
      soft_pull_consent,
      notes,
    },
  };
}

const CONTACT_INTENTS: ContactIntent[] = [
  "adu_project",
  "financing",
  "partner",
  "general",
];

function parseContactBody(
  body: any,
): { ok: true; data: SubmitContactRequest } | { ok: false; error: string } {
  const full_name = String(body?.full_name || body?.name || "").trim();
  const email = normalizeEmail(body?.email);
  const phone = String(body?.phone || "").trim();
  const intent = CONTACT_INTENTS.includes(body?.intent)
    ? (body.intent as ContactIntent)
    : null;
  const preferred_language =
    body?.preferred_language === "es" ? ("es" as const) : ("en" as const);
  const sms_transactional_consent = Boolean(
    body?.sms_transactional_consent === true ||
    body?.sms_transactional_consent === 1 ||
    body?.sms_transactional_consent === "1",
  );
  const sms_marketing_consent = Boolean(
    body?.sms_marketing_consent === true ||
    body?.sms_marketing_consent === 1 ||
    body?.sms_marketing_consent === "1",
  );

  if (!full_name || full_name.length < 2) {
    return { ok: false, error: "validation.nameRequired" };
  }
  if (!isValidEmail(email)) {
    return { ok: false, error: "validation.emailInvalid" };
  }
  if (!phone || phone.replace(/\D/g, "").length < 10) {
    return { ok: false, error: "validation.phoneMin" };
  }
  if (!intent) {
    return { ok: false, error: "validation.intentRequired" };
  }
  if (!sms_transactional_consent) {
    return { ok: false, error: "validation.smsTransactional" };
  }

  const rawRef =
    body?.referral_code != null ? String(body.referral_code).trim() : "";
  const referral_code =
    rawRef && /^[A-Za-z0-9_-]{1,64}$/.test(rawRef) ? rawRef.slice(0, 64) : null;

  return {
    ok: true,
    data: {
      full_name: full_name.slice(0, 200),
      email: email.slice(0, 255),
      phone: phone.slice(0, 40),
      intent,
      preferred_language,
      sms_transactional_consent,
      sms_marketing_consent,
      referral_code,
    },
  };
}

function parsePartnerBody(
  body: any,
):
  | { ok: true; data: SubmitPartnerReferralRequest }
  | { ok: false; error: string } {
  const full_name = String(body?.full_name || body?.name || "").trim();
  const email = normalizeEmail(body?.email);
  const phone = String(body?.phone || "").trim();
  const company = body?.company
    ? String(body.company).trim().slice(0, 200)
    : null;
  const notes = body?.notes ? String(body.notes).trim().slice(0, 2000) : null;
  const preferred_language =
    body?.preferred_language === "es" ? ("es" as const) : ("en" as const);
  const rawRef =
    body?.referral_code != null ? String(body.referral_code).trim() : "";
  const referral_code =
    rawRef && /^[A-Za-z0-9_-]{1,64}$/.test(rawRef) ? rawRef.slice(0, 64) : null;

  if (!full_name || full_name.length < 2) {
    return { ok: false, error: "validation.nameRequired" };
  }
  if (!isValidEmail(email)) {
    return { ok: false, error: "validation.emailInvalid" };
  }
  if (!phone || phone.replace(/\D/g, "").length < 10) {
    return { ok: false, error: "validation.phoneMin" };
  }

  return {
    ok: true,
    data: {
      full_name: full_name.slice(0, 200),
      email: email.slice(0, 255),
      phone: phone.slice(0, 40),
      company,
      notes,
      preferred_language,
      referral_code,
    },
  };
}

/** Parse `company=…` from lead notes (partner_referral historical rows). */
function companyFromLeadNotes(notes: unknown): string | null {
  const m = String(notes || "").match(/company=([^;]+)/i);
  const v = m?.[1]?.trim();
  return v ? v.slice(0, 200) : null;
}

function leadAlreadyConvertedRow(lead: RowDataPacket): boolean {
  return Boolean(
    lead.client_id ||
    lead.converted_affiliate_id ||
    lead.converted_contractor_id,
  );
}

type IdentityEntity = "client" | "affiliate" | "contractor";

async function findIdentityByEmail(
  email: string,
): Promise<{ entity: IdentityEntity; id: number } | null> {
  const e = normalizeEmail(email);
  const [clients] = await pool.execute<RowDataPacket[]>(
    `SELECT id FROM clients WHERE email = ? LIMIT 1`,
    [e],
  );
  if (clients[0]) return { entity: "client", id: Number(clients[0].id) };
  const [affs] = await pool.execute<RowDataPacket[]>(
    `SELECT id FROM affiliates WHERE email = ? LIMIT 1`,
    [e],
  );
  if (affs[0]) return { entity: "affiliate", id: Number(affs[0].id) };
  const [ctrs] = await pool.execute<RowDataPacket[]>(
    `SELECT id FROM contractors WHERE email = ? LIMIT 1`,
    [e],
  );
  if (ctrs[0]) return { entity: "contractor", id: Number(ctrs[0].id) };
  return null;
}

function emailExistsErrorKey(entity: IdentityEntity): string {
  if (entity === "client") return "errors.emailExistsClient";
  if (entity === "affiliate") return "errors.emailExistsAffiliate";
  return "errors.emailExistsContractor";
}

/** Phone match on target table with a different email (decision 7b+c). */
async function findPhoneMatchDifferentEmail(
  entity: IdentityEntity,
  phone: string | null | undefined,
  email: string,
): Promise<LeadConvertPhoneMatch | null> {
  const last10 = normalizePhoneLast10(phone);
  if (!last10) return null;
  const e = normalizeEmail(email);
  const table =
    entity === "client"
      ? "clients"
      : entity === "affiliate"
        ? "affiliates"
        : "contractors";
  const [rows] = await pool.execute<RowDataPacket[]>(
    `SELECT id, email, first_name, last_name, phone FROM \`${table}\`
     WHERE (email IS NULL OR email <> ?) AND phone IS NOT NULL AND TRIM(phone) <> ''
     ORDER BY id DESC LIMIT 200`,
    [e],
  );
  for (const r of rows) {
    if (normalizePhoneLast10(String(r.phone || "")) !== last10) continue;
    return {
      entity,
      id: Number(r.id),
      email: r.email == null ? "" : String(r.email),
      name:
        `${r.first_name || ""} ${r.last_name || ""}`.trim() || String(r.email),
    };
  }
  return null;
}

// ─── People de-duplication (one role per person; email OR phone) ────────────
// Every path that creates a client / affiliate / contractor calls
// assertPersonAvailable() after its own same-role email handling.

const PERSON_ENTITIES: PersonEntity[] = ["client", "affiliate", "contractor"];
const PERSON_TABLE: Record<
  PersonEntity,
  "clients" | "affiliates" | "contractors"
> = {
  client: "clients",
  affiliate: "affiliates",
  contractor: "contractors",
};
/** Last 10 phone digits in SQL (mirrors normalizePhoneLast10). */
const phone10Sql = (col: string) =>
  `RIGHT(REGEXP_REPLACE(IFNULL(${col}, ''), '[^0-9]', ''), 10)`;

type PhoneMatchRow = { role: "client" | "affiliate" | "contractor" | "contact" | "lead" | "staff"; id: number; name: string };
const PHONE_MATCH_ORDER: PhoneMatchRow["role"][] = ["client", "affiliate", "contractor", "contact", "lead", "staff"];

/**
 * Who owns these phone numbers in our records (by last 10 digits). Best match
 * first: client > affiliate > contractor > contact > lead > staff; the rest are
 * listed as `others`. Used to name "unknown" conversation threads.
 */
/** Last-10 phone digits of people whose name or email matches a LIKE pattern (inbox search). */
async function phonesForName(like: string): Promise<string[]> {
  const sources = [
    `SELECT phone FROM clients WHERE CONCAT_WS(' ', first_name, last_name) LIKE ? OR email LIKE ?`,
    `SELECT phone FROM affiliates WHERE CONCAT_WS(' ', first_name, last_name) LIKE ? OR email LIKE ? OR company LIKE ?`,
    `SELECT phone FROM contractors WHERE CONCAT_WS(' ', first_name, last_name) LIKE ? OR email LIKE ? OR company LIKE ?`,
    `SELECT phone FROM contacts WHERE deleted_at IS NULL AND (CONCAT_WS(' ', first_name, last_name) LIKE ? OR email LIKE ?)`,
    `SELECT phone FROM leads WHERE status <> 'spam' AND (full_name LIKE ? OR email LIKE ?)`,
    `SELECT phone FROM admins WHERE CONCAT_WS(' ', first_name, last_name) LIKE ? OR email LIKE ?`,
  ];
  const out = new Set<string>();
  for (const sql of sources) {
    const n = (sql.match(/\?/g) || []).length;
    const [rows] = await pool.query<RowDataPacket[]>(`${sql} LIMIT 200`, Array(n).fill(like));
    for (const r of rows) {
      const k = normalizePhoneLast10(String(r.phone || ""));
      if (k) out.add(k);
    }
  }
  return [...out].slice(0, 500);
}

async function resolvePeopleByPhone(phones: unknown[]) {
  const keys = [...new Set(phones.map((p) => normalizePhoneLast10(String(p || ""))).filter(Boolean))] as string[];
  const out = new Map<string, { role: PhoneMatchRow["role"]; id: number; name: string; others: PhoneMatchRow[] }>();
  if (!keys.length) return out;
  const found = new Map<string, PhoneMatchRow[]>();
  const sources: [PhoneMatchRow["role"], string][] = [
    ["client", `SELECT id, CONCAT_WS(' ', first_name, last_name) name, phone FROM clients WHERE ${phone10Sql("phone")} IN (?)`],
    ["affiliate", `SELECT id, CONCAT_WS(' ', first_name, last_name) name, phone FROM affiliates WHERE ${phone10Sql("phone")} IN (?)`],
    ["contractor", `SELECT id, CONCAT_WS(' ', first_name, last_name) name, phone FROM contractors WHERE ${phone10Sql("phone")} IN (?)`],
    ["contact", `SELECT id, CONCAT_WS(' ', first_name, last_name) name, phone FROM contacts WHERE deleted_at IS NULL AND ${phone10Sql("phone")} IN (?)`],
    ["lead", `SELECT id, full_name name, phone FROM leads WHERE status <> 'spam' AND ${phone10Sql("phone")} IN (?) ORDER BY id DESC`],
    ["staff", `SELECT id, CONCAT_WS(' ', first_name, last_name) name, phone FROM admins WHERE ${phone10Sql("phone")} IN (?)`],
  ];
  for (const [role, sql] of sources) {
    const [rows] = await pool.query<RowDataPacket[]>(`${sql} LIMIT 500`, [keys]);
    for (const r of rows) {
      const k = normalizePhoneLast10(String(r.phone || ""));
      if (!k) continue;
      const list = found.get(k) || [];
      // One entry per role (the newest lead / first record wins within a role).
      if (!list.some((x) => x.role === role)) list.push({ role, id: Number(r.id), name: String(r.name || "").trim() });
      found.set(k, list);
    }
  }
  for (const [k, list] of found) {
    list.sort((a, b) => PHONE_MATCH_ORDER.indexOf(a.role) - PHONE_MATCH_ORDER.indexOf(b.role));
    const [best, ...others] = list.filter((x) => x.name);
    if (best) out.set(k, { ...best, others });
  }
  return out;
}
const SHARED_PHONE_REASON_MIN = 5;

/** Existing clients / affiliates / contractors sharing this email or phone. Email matches first. */
async function findPersonMatches(opts: {
  email?: unknown;
  phone?: unknown;
  exclude?: Array<{ entity: PersonEntity; id: number }>;
  exec?: Pool | PoolConnection;
}): Promise<PersonMatch[]> {
  const exec = opts.exec ?? pool;
  const email = opts.email ? normalizeEmail(opts.email) : "";
  const phone10 = normalizePhoneLast10(
    opts.phone == null ? null : String(opts.phone),
  );
  if (!isValidEmail(email) && !phone10) return [];
  const out: PersonMatch[] = [];
  for (const entity of PERSON_ENTITIES) {
    const conds: string[] = [];
    const params: unknown[] = [];
    if (isValidEmail(email)) {
      conds.push("email = ?");
      params.push(email);
    }
    if (phone10) {
      conds.push(`${phone10Sql("phone")} = ?`);
      params.push(phone10);
    }
    const [rows] = await exec.execute<RowDataPacket[]>(
      `SELECT id, email, first_name, last_name, phone, status
       FROM \`${PERSON_TABLE[entity]}\` WHERE ${conds.join(" OR ")}
       ORDER BY id ASC LIMIT 10`,
      params as any[],
    );
    for (const r of rows) {
      const id = Number(r.id);
      if (opts.exclude?.some((x) => x.entity === entity && x.id === id))
        continue;
      const rowEmail = r.email == null ? null : normalizeEmail(r.email);
      out.push({
        entity,
        id,
        name:
          `${r.first_name || ""} ${r.last_name || ""}`.trim() ||
          rowEmail ||
          `#${id}`,
        email: rowEmail,
        phone: r.phone == null ? null : String(r.phone),
        status: String(r.status || ""),
        by: isValidEmail(email) && rowEmail === email ? "email" : "phone",
      });
    }
  }
  return out.sort((a, b) => (a.by === b.by ? 0 : a.by === "email" ? -1 : 1));
}

type PersonActor = "public" | "affiliate" | "staff";

/**
 * One role per person. Throws 409 when the email or phone already belongs to
 * someone. Staff may pass a shared-phone reason to allow a phone-only match
 * (e.g. a household phone); email matches always block. Public responses never
 * reveal who matched.
 */
async function assertPersonAvailable(opts: {
  email?: unknown;
  phone?: unknown;
  actor: PersonActor;
  sharedPhoneReason?: unknown;
  exclude?: Array<{ entity: PersonEntity; id: number }>;
  exec?: Pool | PoolConnection;
}): Promise<{
  phoneOverride: { reason: string; matches: PersonMatch[] } | null;
}> {
  const matches = await findPersonMatches(opts);
  if (!matches.length) return { phoneOverride: null };
  const first = matches[0];
  if (opts.actor === "public")
    throw new HttpError(409, "errors.personExistsPublic", { duplicate: first });
  if (opts.actor === "affiliate") {
    throw new HttpError(409, "errors.personExistsAffiliate", {
      match: { entity: first.entity },
    });
  }
  if (first.by === "email")
    throw new HttpError(409, "errors.personExists", { match: first });
  const reason = String(opts.sharedPhoneReason ?? "")
    .trim()
    .slice(0, 500);
  if (reason.length < SHARED_PHONE_REASON_MIN) {
    throw new HttpError(409, "errors.personPhoneMatch", {
      match: first,
      can_override: true,
    });
  }
  return { phoneOverride: { reason, matches } };
}

/** Public 409s carry the match for staff alerts only — strip it before responding. */
function stripPublicDuplicate(e: HttpError): HttpError {
  return new HttpError(e.status, e.key);
}

async function logDedupe(opts: {
  action:
    | "merge"
    | "delete"
    | "phone_override"
    | "link"
    | "dismiss"
    | "blocked"
    | "revert"
    | "email_change";
  entity: DedupeEntity;
  recordId?: number | null;
  targetEntity?: DedupeEntity | null;
  targetId?: number | null;
  adminId?: number | null;
  reason?: string | null;
  snapshot?: unknown;
  exec?: Pool | PoolConnection;
}) {
  await (opts.exec ?? pool).execute(
    `INSERT INTO people_dedupe_log
       (action, entity, record_id, target_entity, target_id, admin_id, reason, snapshot_json)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      opts.action,
      opts.entity,
      opts.recordId ?? null,
      opts.targetEntity ?? null,
      opts.targetId ?? null,
      opts.adminId ?? null,
      opts.reason ? String(opts.reason).slice(0, 500) : null,
      opts.snapshot === undefined ? null : JSON.stringify(opts.snapshot),
    ],
  );
}

const dedupeSignature = (keys: string[]) =>
  [...new Set(keys)].sort().join("|").slice(0, 500);

/** After a staff shared-phone override: audit it and keep that cluster out of the review queue. */
async function recordSharedPhoneOverride(opts: {
  entity: PersonEntity;
  id: number;
  override: { reason: string; matches: PersonMatch[] };
  adminId: number | null;
}) {
  for (const m of opts.override.matches) {
    await logDedupe({
      action: "phone_override",
      entity: opts.entity,
      recordId: opts.id,
      targetEntity: m.entity,
      targetId: m.id,
      adminId: opts.adminId,
      reason: opts.override.reason,
    });
  }
  const signature = dedupeSignature([
    `${opts.entity}:${opts.id}`,
    ...opts.override.matches.map((m) => `${m.entity}:${m.id}`),
  ]);
  await pool.execute(
    `INSERT INTO people_dedupe_dismissals (signature, admin_id, reason) VALUES (?, ?, ?)
     ON DUPLICATE KEY UPDATE reason = VALUES(reason)`,
    [signature, opts.adminId, opts.override.reason],
  );
}

/** A public signup / form was refused as a duplicate: audit + tell staff (visitor sees a generic note). */
async function reportBlockedPublicDuplicate(opts: {
  source: string;
  attempted: PersonEntity;
  name: string;
  email: string;
  phone: string | null;
  match: PersonMatch;
}) {
  try {
    await logDedupe({
      action: "blocked",
      entity: opts.match.entity,
      recordId: opts.match.id,
      targetEntity: opts.attempted,
      reason: `${opts.source}: ${opts.name} <${opts.email}>`.slice(0, 500),
    });
  } catch (e: any) {
    console.error("[dedupe] log blocked failed:", e?.message ?? e);
  }
  const path = `/admin/${PERSON_TABLE[opts.match.entity]}/${opts.match.id}`;
  await notifyStaff("duplicate_blocked", (l) => ({
    subject: tr(
      l,
      `Duplicate signup blocked · ${opts.name}`,
      `Registro duplicado bloqueado · ${opts.name}`,
    ),
    headline: tr(
      l,
      "Someone already on file tried to sign up again",
      "Alguien ya registrado intentó registrarse de nuevo",
    ),
    paragraphs: [
      tr(
        l,
        `A ${opts.source} submission matched an existing ${opts.match.entity} by ${opts.match.by}. No new record was created.`,
        `Un envío de ${opts.source} coincidió por ${opts.match.by === "email" ? "correo" : "teléfono"} con un registro existente. No se creó un registro nuevo.`,
      ),
    ],
    details: [
      [
        tr(l, "Submitted", "Enviado"),
        `${opts.name} · ${opts.email}${opts.phone ? ` · ${opts.phone}` : ""}`,
      ],
      [
        tr(l, "Existing record", "Registro existente"),
        `${opts.match.entity} #${opts.match.id} · ${opts.match.name}`,
      ],
      [tr(l, "Attempted role", "Rol intentado"), opts.attempted],
    ],
    cta: {
      url: `${APP_URL}${path}`,
      label: tr(l, "Open existing record", "Abrir registro existente"),
    },
  }));
}

/**
 * Public flows: run the one-role check; on a match, alert staff and rethrow a
 * generic 409 (`errors.personExistsPublic`) that never says who matched.
 */
async function assertPublicPersonAvailable(opts: {
  source: string;
  attempted: PersonEntity;
  name: string;
  email: string;
  phone: string | null;
  exclude?: Array<{ entity: PersonEntity; id: number }>;
}) {
  try {
    await assertPersonAvailable({
      email: opts.email,
      phone: opts.phone,
      actor: "public",
      exclude: opts.exclude,
    });
  } catch (e) {
    if (
      e instanceof HttpError &&
      e.key === "errors.personExistsPublic" &&
      e.data?.duplicate
    ) {
      await reportBlockedPublicDuplicate({
        ...opts,
        match: e.data.duplicate as PersonMatch,
      });
      throw stripPublicDuplicate(e);
    }
    throw e;
  }
}

/** Portal self-signups: true when the person already exists (staff alerted; caller answers outcome "exists"). */
async function isPublicSignupDuplicate(
  opts: Parameters<typeof assertPublicPersonAvailable>[0],
): Promise<boolean> {
  try {
    await assertPublicPersonAvailable(opts);
    return false;
  } catch (e) {
    if (e instanceof HttpError && e.key === "errors.personExistsPublic")
      return true;
    throw e;
  }
}

/** Editing an email / phone must not collide with another person (one role per person). */
async function assertIdentityEditAllowed(opts: {
  entity: PersonEntity;
  id: number;
  updates: Record<string, any>;
  actor: PersonActor;
  sharedPhoneReason?: unknown;
  adminId?: number | null;
}) {
  // Only values that actually change are checked (saving other fields never trips on legacy duplicates).
  const [cur] = await pool.execute<RowDataPacket[]>(
    `SELECT email, phone FROM \`${PERSON_TABLE[opts.entity]}\` WHERE id = ? LIMIT 1`,
    [opts.id],
  );
  const prevEmail = cur[0]?.email ? normalizeEmail(cur[0].email) : null;
  const prevPhone = normalizePhoneLast10(cur[0]?.phone ?? null);
  const nextEmail =
    "email" in opts.updates && opts.updates.email
      ? normalizeEmail(opts.updates.email)
      : null;
  const nextPhone =
    "phone" in opts.updates && opts.updates.phone
      ? String(opts.updates.phone)
      : null;
  const email = nextEmail && nextEmail !== prevEmail ? nextEmail : null;
  const phone =
    nextPhone && normalizePhoneLast10(nextPhone) !== prevPhone
      ? nextPhone
      : null;
  if (!email && !phone) return;
  const { phoneOverride } = await assertPersonAvailable({
    email,
    phone,
    actor: opts.actor,
    sharedPhoneReason: opts.sharedPhoneReason,
    exclude: [{ entity: opts.entity, id: opts.id }],
  });
  if (phoneOverride) {
    await recordSharedPhoneOverride({
      entity: opts.entity,
      id: opts.id,
      override: phoneOverride,
      adminId: opts.adminId ?? null,
    });
  }
}

// ── Leads: one standard lead per person (repeat submissions merge) ──────────

type PublicLeadInput = {
  first_name: string;
  last_name: string;
  full_name: string;
  email: string;
  phone: string;
  property_address: string | null;
  soft_pull_consent: boolean;
  sms_marketing_consent?: boolean;
  source: string;
  preferred_language: string;
  notes: string | null;
  affiliate_id: number | null;
  referral_code: string | null;
  status: "new" | "qualified";
  ip: string | null;
  ua: string | null;
};

/**
 * Standard (non-event) public lead: merge into this person's existing lead by
 * email OR phone (bump to the top, count + timestamp, append the submission
 * to notes, fill blanks) instead of inserting a new row. Spam leads never merge.
 */
async function upsertStandardLead(
  input: PublicLeadInput,
  exec: Pool | PoolConnection = pool,
): Promise<{ id: number; merged: boolean }> {
  const email = normalizeEmail(input.email);
  const phone10 = normalizePhoneLast10(input.phone);
  const [found] = await exec.execute<RowDataPacket[]>(
    `SELECT id FROM leads
     WHERE event_id IS NULL AND status <> 'spam'
       AND (email = ? ${phone10 ? `OR ${phone10Sql("phone")} = ?` : ""})
     ORDER BY (email = ?) DESC, id DESC LIMIT 1`,
    phone10 ? [email, phone10, email] : [email, email],
  );
  const stamp = new Date().toISOString().slice(0, 16).replace("T", " ");
  const entry = [
    `[${stamp} UTC] Resubmitted via ${input.source}`,
    `${input.full_name} · ${email} · ${input.phone}`,
    input.property_address ? `Address: ${input.property_address}` : null,
    input.notes,
  ]
    .filter(Boolean)
    .join(" · ");
  if (found[0]) {
    const id = Number(found[0].id);
    await exec.execute(
      `UPDATE leads SET
         submission_count = submission_count + 1,
         last_submitted_at = NOW(),
         notes = LEFT(CONCAT_WS('\\n', NULLIF(notes, ''), ?), 60000),
         first_name = COALESCE(NULLIF(first_name, ''), ?),
         last_name = COALESCE(NULLIF(last_name, ''), ?),
         property_address = COALESCE(NULLIF(property_address, ''), ?),
         soft_pull_consent = GREATEST(soft_pull_consent, ?),
         sms_marketing_consent = GREATEST(sms_marketing_consent, ?),
         affiliate_id = COALESCE(affiliate_id, ?),
         referral_code = COALESCE(referral_code, ?),
         status = CASE WHEN status = 'closed' THEN 'new' ELSE status END
       WHERE id = ?`,
      [
        entry,
        input.first_name || null,
        input.last_name || null,
        input.property_address,
        input.soft_pull_consent ? 1 : 0,
        input.sms_marketing_consent ? 1 : 0,
        input.affiliate_id,
        input.referral_code,
        id,
      ],
    );
    await linkLeadToPerson(id, exec);
    return { id, merged: true };
  }
  const [ins] = await exec.execute<ResultSetHeader>(
    `INSERT INTO leads (
       first_name, last_name, full_name, email, phone, property_address,
       soft_pull_consent, sms_marketing_consent, mode, source, preferred_language, notes,
       affiliate_id, referral_code, status, ip_address, user_agent
     ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'standard', ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      input.first_name.slice(0, 100),
      input.last_name.slice(0, 100),
      input.full_name.slice(0, 200),
      email,
      input.phone,
      input.property_address,
      input.soft_pull_consent ? 1 : 0,
      input.sms_marketing_consent ? 1 : 0,
      input.source,
      input.preferred_language === "es" ? "es" : "en",
      input.notes,
      input.affiliate_id,
      input.referral_code,
      input.status,
      input.ip,
      input.ua,
    ],
  );
  const id = Number(ins.insertId);
  await linkLeadToPerson(id, exec);
  return { id, merged: false };
}

/** Point an unlinked lead at the person it already is (so Convert disappears). */
async function linkLeadToPerson(
  leadId: number,
  exec: Pool | PoolConnection = pool,
) {
  const [rows] = await exec.execute<RowDataPacket[]>(
    `SELECT email, phone, client_id, converted_affiliate_id, converted_contractor_id
     FROM leads WHERE id = ? LIMIT 1`,
    [leadId],
  );
  const l = rows[0];
  if (
    !l ||
    l.client_id ||
    l.converted_affiliate_id ||
    l.converted_contractor_id
  )
    return;
  const [m] = await findPersonMatches({ email: l.email, phone: l.phone, exec });
  if (!m) return;
  const col =
    m.entity === "client"
      ? "client_id"
      : m.entity === "affiliate"
        ? "converted_affiliate_id"
        : "converted_contractor_id";
  await exec.execute(
    `UPDATE leads SET ${col} = ? WHERE id = ? AND ${col} IS NULL`,
    [m.id, leadId],
  );
}


/** Who a partner is: Realtor (company + DRE #), Lender (company + NMLS #) or neither. */
type PartnerType = "realtor" | "lender" | "other";
function parsePartnerType(b: any, company: string | null): { partner_type: PartnerType | null; license_number: string | null } {
  const raw = String(b?.partner_type || "").trim().toLowerCase();
  if (!raw) return { partner_type: null, license_number: null };
  if (!["realtor", "lender", "other"].includes(raw)) throw new HttpError(400, "validation.invalidField");
  const partner_type = raw as PartnerType;
  if (partner_type === "other") return { partner_type, license_number: null };
  const license = String(b?.license_number || "").trim().replace(/\s+/g, " ").slice(0, 40);
  if (!company) throw new HttpError(400, "validation.partnerCompany");
  if (license.length < 3) throw new HttpError(400, partner_type === "realtor" ? "validation.dreRequired" : "validation.nmlsRequired");
  return { partner_type, license_number: license };
}

/** Project loan_lender_type from the chosen lender: Anchor (synced) vs any other lender. */
function lenderTypeFor(company: string | null): "anchor" | "external" | "unknown" {
  if (!company) return "unknown";
  return /\banchor\b/i.test(company) ? "anchor" : "external";
}


// ── Lead role answers: "Reply A (Homeowner), B (Affiliate / Partner), C (Contractor)" to an automation text ──

type LeadRole = "homeowner" | "partner" | "contractor";
const LEAD_ROLE_PATH: Record<LeadRole, string> = { homeowner: "/start", partner: "/affiliate/signup", contractor: "/contractor/signup" };
const leadRoleLink = (token: string, role: LeadRole) => `${APP_URL}${LEAD_ROLE_PATH[role]}?t=${token}`;

/** "A", "b.", "Homeowner", "afiliado"… → role. Only short, clear answers count. */
export function leadRoleFromReply(body: string): LeadRole | null {
  const v = String(body || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z ]/g, " ")
    .trim()
    .replace(/\s+/g, " ");
  if (!v || v.length > 30) return null;
  if (/^(a|option a|homeowner|home owner|propietario|dueno|owner)$/.test(v)) return "homeowner";
  if (/^(b|option b|affiliate|partner|referral partner|affiliate partner|realtor|afiliado|socio|referidor)$/.test(v)) return "partner";
  if (/^(c|option c|contractor|contratista|builder)$/.test(v)) return "contractor";
  return null;
}

/** A lead got an automation text: their A / B / C reply (30 days) is recognized. Keeps an existing token. */
async function markLeadRolePrompt(leadId: number): Promise<void> {
  await pool.execute(
    `UPDATE leads SET role_token = COALESCE(role_token, ?), role_prompt_sent_at = NOW() WHERE id = ? AND role_answer IS NULL`,
    [crypto.randomBytes(16).toString("hex"), leadId],
  );
}

/** Store the answer (first one wins), send the right application link, tell staff. */
async function recordLeadRole(leadId: number, role: LeadRole, via: "sms" | "email"): Promise<{ token: string } | null> {
  const [[l]] = (await pool.query<RowDataPacket[]>(`SELECT id, full_name, email, phone, preferred_language, role_token, role_answer FROM leads WHERE id = ?`, [leadId])) as unknown as [RowDataPacket[]];
  if (!l?.role_token) return null;
  const token = String(l.role_token);
  if (l.role_answer) return { token };
  await pool.execute(`UPDATE leads SET role_answer = ?, role_answered_at = NOW(), status = IF(status = 'new', 'contacted', status) WHERE id = ? AND role_answer IS NULL`, [role, leadId]);
  const lang = asLang(l.preferred_language);
  const label = { homeowner: tr(lang, "homeowner application", "solicitud de propietario"), partner: tr(lang, "affiliate application", "solicitud de afiliado"), contractor: tr(lang, "contractor application", "solicitud de contratista") }[role];
  if (via === "sms" && l.phone) {
    const from = await resolveCampaignSmsFrom().catch(() => null);
    if (from)
      await sendSms({
        to: String(l.phone),
        from,
        body: tr(lang, `Groundwork Capital Group: Thank you! Here is your ${label}, it takes about two minutes: ${leadRoleLink(token, role)}`, `Groundwork Capital Group: ¡Gracias! Aquí está tu ${label}, toma unos dos minutos: ${leadRoleLink(token, role)}`),
      }).catch((e: any) => console.warn("[lead-role:reply]", e?.message ?? e));
  }
  const roleName = (l2: Lang) => ({ homeowner: tr(l2, "Homeowner", "Propietario"), partner: tr(l2, "Affiliate / Partner", "Afiliado / Socio"), contractor: tr(l2, "Contractor", "Contratista") })[role];
  await startFlows(role === "homeowner" ? "homeowner_lead" : role === "partner" ? "lead_answer_partner" : "lead_answer_contractor", "lead", leadId);
  await notifyStaff("lead_submitted", (l2) => ({
    subject: tr(l2, `Lead answered: ${roleName(l2)} · ${l.full_name}`, `Prospecto respondió: ${roleName(l2)} · ${l.full_name}`),
    headline: tr(l2, `${l.full_name} is a ${roleName(l2)}`, `${l.full_name} es ${roleName(l2)}`),
    paragraphs: [
      tr(l2, `They answered the welcome message (${via === "sms" ? "text" : "email"}) and got the ${roleName(l2)} application link.`, `Respondió el mensaje de bienvenida (${via === "sms" ? "texto" : "correo"}) y recibió el enlace de la solicitud de ${roleName(l2)}.`),
    ],
    details: [
      ["Email", String(l.email || "—")],
      [tr(l2, "Phone", "Teléfono"), String(l.phone || "—")],
    ],
    cta: { url: `${APP_URL}/admin/leads?q=${encodeURIComponent(String(l.email || l.full_name))}`, label: tr(l2, "Open lead", "Abrir prospecto") },
  }));
  return { token };
}

/** Inbound text: a lead who got the A/B/C prompt (last 30 days) and hasn't answered yet. */
async function tryHandleLeadRoleReply(opts: { fromPhone: string; body: string }): Promise<boolean> {
  const role = leadRoleFromReply(opts.body);
  if (!role) return false;
  const last10 = normalizePhoneLast10(opts.fromPhone);
  if (!last10) return false;
  const [[l]] = (await pool.query<RowDataPacket[]>(
    `SELECT id FROM leads WHERE ${phone10Sql("phone")} = ? AND role_prompt_sent_at >= NOW() - INTERVAL 30 DAY AND role_answer IS NULL
     ORDER BY role_prompt_sent_at DESC LIMIT 1`,
    [last10],
  )) as unknown as [RowDataPacket[]];
  if (!l) return false;
  await recordLeadRole(Number(l.id), role, "sms");
  return true;
}

/** Approved lender affiliates appear in the Lenders directory (dropdowns on clients / projects / appointments). */
async function ensureLenderForAffiliate(affiliateId: number): Promise<number | null> {
  const [[a]] = (await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name, email, phone, company, preferred_language, partner_type, license_number, lender_id, status FROM affiliates WHERE id = ?`,
    [affiliateId],
  )) as unknown as [RowDataPacket[]];
  if (!a || a.partner_type !== "lender" || String(a.status) !== "active") return null;
  if (a.lender_id) return Number(a.lender_id);
  const [[match]] = (await pool.query<RowDataPacket[]>(
    `SELECT id FROM lenders WHERE affiliate_id = ? OR (? <> '' AND nmls_number = ?) OR (? <> '' AND LOWER(email) = ?) ORDER BY affiliate_id = ? DESC LIMIT 1`,
    [affiliateId, a.license_number || "", a.license_number || "", a.email || "", String(a.email || "").toLowerCase(), affiliateId],
  )) as unknown as [RowDataPacket[]];
  let lenderId: number;
  if (match) {
    lenderId = Number(match.id);
    await pool.execute(
      `UPDATE lenders SET affiliate_id = ?, nmls_number = COALESCE(nmls_number, ?), is_active = 1 WHERE id = ?`,
      [affiliateId, a.license_number || null, lenderId],
    );
  } else {
    const [ins] = await pool.execute<ResultSetHeader>(
      `INSERT INTO lenders (company, contact_name, email, phone, preferred_language, nmls_number, affiliate_id, notes, is_active)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)`,
      [
        String(a.company || `${a.first_name} ${a.last_name}`).slice(0, 200),
        `${a.first_name} ${a.last_name}`.trim().slice(0, 200),
        a.email || null,
        a.phone || null,
        asLang(a.preferred_language),
        a.license_number || null,
        affiliateId,
        "Joined as an affiliate (lender).",
      ],
    );
    lenderId = Number(ins.insertId);
  }
  await pool.execute(`UPDATE affiliates SET lender_id = ? WHERE id = ?`, [lenderId, affiliateId]);
  return lenderId;
}

/** Public Partners / contact intent=partner → pending affiliate (no lead). */
async function createPendingPartnerAffiliate(opts: {
  full_name: string;
  email: string;
  phone: string;
  company?: string | null;
  notes?: string | null;
  preferred_language?: "en" | "es";
  referral_code?: string | null;
  notifySource: "partners" | "contact";
  partner_type?: PartnerType | null;
  license_number?: string | null;
  sms_marketing_consent?: boolean;
}): Promise<{ affiliate_id: number }> {
  const email = normalizeEmail(opts.email);
  const nameParts = opts.full_name.trim().split(/\s+/);
  const firstName = (nameParts[0] || opts.full_name).slice(0, 100);
  const lastName = (nameParts.slice(1).join(" ") || firstName).slice(0, 100);
  const lang = asLang(opts.preferred_language);
  const company = opts.company || null;
  const notes = opts.notes || null;

  const [existing] = await pool.execute<RowDataPacket[]>(
    `SELECT id FROM affiliates WHERE email = ? LIMIT 1`,
    [email],
  );
  if (existing.length) throw new HttpError(409, "errors.affiliateExists");
  // One role per person (email OR phone across clients / affiliates / contractors).
  await assertPublicPersonAvailable({
    source:
      opts.notifySource === "partners"
        ? "partner referral"
        : "contact form (partner)",
    attempted: "affiliate",
    name: opts.full_name,
    email,
    phone: opts.phone,
  });

  const parent = await findActiveAffiliateByCode(opts.referral_code);
  const affiliateId = await withNewAffiliateCodes(
    firstName,
    lastName,
    async ({ code, slug }) => {
      const [result] = await pool.execute<ResultSetHeader>(
        `INSERT INTO affiliates
         (email, first_name, last_name, phone, company, status, preferred_language,
          referral_code, slug, parent_affiliate_id, notes, partner_type, license_number, sms_marketing_consent)
       VALUES (?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          email,
          firstName,
          lastName,
          opts.phone,
          company,
          lang,
          code,
          slug,
          parent?.id ?? null,
          notes,
          opts.partner_type ?? null,
          opts.license_number ?? null,
          opts.sms_marketing_consent ? 1 : 0,
        ],
      );
      return Number(result.insertId);
    },
  );

  // Welcome email + text: presentation + secure link (agreement, W-9, card).
  await sendAffiliateWelcome(affiliateId);
  await startFlows("affiliate_signup", "affiliate", affiliateId);

  await notifyStaff("partner_referral", (l) => ({
    subject: tr(
      l,
      `Partner application (pending affiliate): ${firstName} ${lastName}`,
      `Solicitud de socio (afiliado pendiente): ${firstName} ${lastName}`,
    ),
    headline: tr(
      l,
      "New partner → pending affiliate",
      "Nuevo socio → afiliado pendiente",
    ),
    paragraphs: [
      opts.notifySource === "contact"
        ? tr(
            l,
            "Contact form (intent=partner) created a pending affiliate. Review in Admin → Affiliates.",
            "Formulario de contacto (intent=partner) creó un afiliado pendiente. Revisa en Admin → Afiliados.",
          )
        : tr(
            l,
            "Partners form created a pending affiliate. Review and approve in Admin → Affiliates.",
            "El formulario de socios creó un afiliado pendiente. Revisa y aprueba en Admin → Afiliados.",
          ),
    ],
    details: [
      [tr(l, "Name", "Nombre"), `${firstName} ${lastName}`],
      ["Email", email],
      [tr(l, "Phone", "Teléfono"), opts.phone],
      [tr(l, "Company", "Empresa"), company || "—"],
      [
        tr(l, "Parent", "Padre"),
        parent ? `#${parent.id} (${parent.referral_code})` : "—",
      ],
      [
        tr(l, "Source", "Fuente"),
        opts.notifySource === "contact" ? "contact" : "partners",
      ],
    ],
    cta: {
      url: `${APP_URL}/admin/affiliates/${affiliateId}`,
      label: tr(l, "Open affiliate", "Abrir afiliado"),
    },
  }));

  return { affiliate_id: affiliateId };
}

