  app.post(
    "/api/admin/clients",
    requireAdmin("people.write"),
    route(async (req, res) => {
      const user = portalUser(res);
      const b = req.body || {};
      const email = normalizeEmail(b.email);
      const first = String(b.first_name || "")
        .trim()
        .slice(0, 100);
      const last = String(b.last_name || "")
        .trim()
        .slice(0, 100);
      if (!isValidEmail(email))
        throw new HttpError(400, "validation.emailInvalid");
      if (!first) throw new HttpError(400, "validation.firstNameRequired");
      if (!last) throw new HttpError(400, "validation.lastNameRequired");
      const affiliateId = b.affiliate_id ? parseId(b.affiliate_id) : null;
      if (affiliateId) {
        const [a] = await pool.execute<RowDataPacket[]>(
          `SELECT id, status FROM affiliates WHERE id = ? LIMIT 1`,
          [affiliateId],
        );
        if (!a[0]) throw new HttpError(400, "errors.invalidReference");
        if (a[0].status !== "active")
          throw new HttpError(400, "errors.affiliateInactive");
      }
      // One role per person; staff may confirm a shared (household) phone with a reason.
      const { phoneOverride } = await assertPersonAvailable({
        email,
        phone: b.phone,
        actor: "staff",
        sharedPhoneReason: b.shared_phone_reason,
      });
      const city = await resolveCity(b.city_id, b.city);
      const [r] = await pool.execute<ResultSetHeader>(
        `INSERT INTO clients
           (email, first_name, last_name, phone, preferred_language, status,
            address_line1, city, city_id, zip, affiliate_id, assigned_admin_id)
         VALUES (?, ?, ?, ?, ?, 'prospect', ?, ?, ?, ?, ?, ?)`,
        [
          email,
          first,
          last,
          b.phone ? String(b.phone).trim().slice(0, 40) : null,
          asLang(b.preferred_language),
          b.address_line1 ? String(b.address_line1).trim().slice(0, 255) : null,
          city.text,
          city.city_id,
          b.zip ? String(b.zip).trim().slice(0, 20) : null,
          affiliateId,
          user.id,
        ],
      );
      const clientId = Number(r.insertId);
      if (phoneOverride) {
        await recordSharedPhoneOverride({
          entity: "client",
          id: clientId,
          override: phoneOverride,
          adminId: user.id,
        });
      }
      await notifyStaff("client_created", (l) => ({
        subject: tr(
          l,
          `Client added · ${first} ${last}`,
          `Cliente agregado · ${first} ${last}`,
        ),
        headline: tr(l, "New client on file.", "Nuevo cliente registrado."),
        paragraphs: [
          tr(
            l,
            `${first} ${last} (${email}) was added as a prospect.`,
            `${first} ${last} (${email}) se agregó como prospecto.`,
          ),
        ],
        cta: {
          url: `${APP_URL}/admin/clients/${clientId}`,
          label: tr(l, "Open client", "Abrir cliente"),
        },
      }), { clientId });
      // Portal invite (email + text) unless staff unchecked it.
      let inviteSent = false;
      if (b.send_invite !== false) {
        const token = await issueClientPortalInvite(pool, { clientId, email, byType: "admin", byId: user.id });
        await sendClientPortalInviteEmail({
          email,
          firstName: first,
          lang: asLang(b.preferred_language),
          token,
          phone: b.phone ? String(b.phone).trim() : null,
        });
        inviteSent = true;
      }
      res.status(201).json({ ok: true, client_id: clientId, invite_sent: inviteSent });
    }),
  );

  app.patch(
    "/api/admin/clients/:id",
    requireAdmin("people.write"),
    route(async (req, res) => {
      const user = portalUser(res);
      const id = parseId(req.params.id);
      const { updates } = parsePatch(req.body, {
        first_name: fStr(100, { min: 1 }),
        last_name: fStr(100, { min: 1 }),
        email: (v) => {
          if (v === null || v === undefined || v === "") {
            return { ok: true, value: null };
          }
          return fEmail(v);
        },
        phone: fStr(40),
        status: fEnum([
          "pending",
          "prospect",
          "active",
          "inactive",
          "suspended",
        ] as const),
        address_line1: fStr(255),
        city: fStr(100),
        zip: fStr(20),
        affiliate_id: fInt(1),
        assigned_admin_id: fInt(1),
        admin_notes: fStr(5000),
        preferred_language: fLang,
      });
      await applyCityPatch(req.body || {}, updates, "city");
      const [rows] = await pool.execute<RowDataPacket[]>(
        `SELECT * FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!rows[0]) throw new HttpError(404, "errors.notFound");
      const prev = rows[0];
      // Lender (directory). Projects that followed the old lender (or had none) follow the new one.
      let lenderChange: { id: number | null; company: string | null } | null = null;
      if (Object.prototype.hasOwnProperty.call(req.body || {}, "lender_id")) {
        const raw = req.body.lender_id;
        if (raw == null || raw === "") lenderChange = { id: null, company: null };
        else {
          const [[ld]] = (await pool.query<RowDataPacket[]>(`SELECT id, company FROM lenders WHERE id = ?`, [parseId(raw)])) as unknown as [RowDataPacket[]];
          if (!ld) throw new HttpError(400, "validation.invalidReference");
          lenderChange = { id: Number(ld.id), company: String(ld.company) };
        }
        updates.lender_id = lenderChange.id;
      }
      if ("email" in updates && updates.email) {
        const [dup] = await pool.execute<RowDataPacket[]>(
          `SELECT id FROM clients WHERE LOWER(email) = ? AND id <> ? LIMIT 1`,
          [updates.email, id],
        );
        if (dup[0]) throw new HttpError(409, "errors.duplicate");
      }
      if (updates.affiliate_id) {
        const [a] = await pool.execute<RowDataPacket[]>(
          `SELECT id, status FROM affiliates WHERE id = ? LIMIT 1`,
          [updates.affiliate_id],
        );
        if (!a[0]) throw new HttpError(400, "errors.invalidReference");
        if (a[0].status !== "active")
          throw new HttpError(400, "errors.affiliateInactive");
      }
      const approving =
        updates.status === "prospect" && String(prev.status) === "pending";
      if (approving && !adminCan(user.role, "approvals")) {
        throw new HttpError(403, "errors.forbidden");
      }
      const emailAfter =
        "email" in updates
          ? updates.email
          : prev.email
            ? String(prev.email)
            : null;
      if (approving && !emailAfter) {
        throw new HttpError(400, "validation.emailRequired");
      }
      await assertIdentityEditAllowed({
        entity: "client",
        id: id,
        updates,
        actor: "staff",
        sharedPhoneReason: req.body?.shared_phone_reason,
        adminId: portalUser(res).id,
      });
      await applyUpdate(pool, "clients", id, updates);
      if (lenderChange) {
        const oldId = prev.lender_id != null ? Number(prev.lender_id) : null;
        await pool.execute(
          `UPDATE projects SET lender_id = ?, loan_lender_name = ?, loan_lender_type = ?
           WHERE client_id = ? AND (lender_id IS NULL OR lender_id = ?)`,
          [lenderChange.id, lenderChange.company, lenderTypeFor(lenderChange.company), id, oldId ?? 0],
        );
      }
      if ("email" in updates) {
        await afterIdentityEmailChange({
          entity: "client",
          id,
          oldEmail: prev.email ? String(prev.email) : null,
          newEmail: updates.email ? String(updates.email) : null,
          firstName: String(updates.first_name ?? prev.first_name ?? ""),
          lang: asLang(updates.preferred_language ?? prev.preferred_language),
          adminId: user.id,
        });
      }
      if (approving) {
        const token = await issueClientPortalInvite(pool, {
          clientId: id,
          email: String(emailAfter),
          byType: "admin",
          byId: user.id,
        });
        await sendClientPortalInviteEmail({
          email: String(emailAfter),
          firstName: String(
            ("first_name" in updates ? updates.first_name : prev.first_name) ||
              "",
          ),
          lang: asLang(
            "preferred_language" in updates
              ? updates.preferred_language
              : prev.preferred_language,
          ),
          token,
        });
      }
      res.json({ ok: true, invite_sent: approving || undefined });
    }),
  );

