  app.post(
    "/api/admin/conversation-templates",
    requireAdmin(),
    route(async (req, res) => {
      const me = portalUser(res);
      const role = String(me.role || "");
      if (!SHARED_LINE_ROLES.includes(role)) {
        throw new HttpError(403, "errors.forbidden");
      }
      const title = String(req.body?.title || "")
        .trim()
        .slice(0, 120);
      const bodyEn = decodeLiteralUnicodeEscapes(
        String(req.body?.body_en || ""),
      ).trim();
      const bodyEsRaw = decodeLiteralUnicodeEscapes(
        String(req.body?.body_es || ""),
      ).trim();
      if (!title || !bodyEn)
        throw new HttpError(400, "validation.invalidField");
      const channel = req.body?.channel === "email" ? "email" : "sms";
      const subjectEn = String(req.body?.subject_en || "").trim().slice(0, 300) || null;
      if (channel === "email" && !subjectEn) throw new HttpError(400, "validation.mailSubject");
      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO conversation_templates
           (title, channel, subject_en, subject_es, body_en, body_es, category, is_active, sort_order, created_by_admin_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)`,
        [
          title,
          channel,
          channel === "email" ? subjectEn : null,
          channel === "email" ? String(req.body?.subject_es || "").trim().slice(0, 300) || null : null,
          bodyEn,
          bodyEsRaw || null,
          CONVERSATION_TEMPLATE_CATEGORIES.includes(String(req.body?.category))
            ? String(req.body.category)
            : "general",
          Number(req.body?.sort_order) || 0,
          me.id,
        ],
      );
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM conversation_templates WHERE id = ? LIMIT 1`,
        [ins.insertId],
      );
      res.status(201).json({ template: mapConversationTemplateRow(rows[0]) });
    }),
  );

  app.patch(
    "/api/admin/conversation-templates/:id",
    requireAdmin(),
    route(async (req, res) => {
      const me = portalUser(res);
      const role = String(me.role || "");
      if (!SHARED_LINE_ROLES.includes(role)) {
        throw new HttpError(403, "errors.forbidden");
      }
      const id = parseId(req.params.id);
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM conversation_templates WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!existing[0]) throw new HttpError(404, "errors.notFound");
      const sets: string[] = [];
      const args: any[] = [];
      if (req.body?.title !== undefined) {
        const title = String(req.body.title || "")
          .trim()
          .slice(0, 120);
        if (!title) throw new HttpError(400, "validation.invalidField");
        sets.push("title = ?");
        args.push(title);
      }
      if (req.body?.body_en !== undefined) {
        const bodyEn = decodeLiteralUnicodeEscapes(
          String(req.body.body_en || ""),
        ).trim();
        if (!bodyEn) throw new HttpError(400, "validation.invalidField");
        sets.push("body_en = ?");
        args.push(bodyEn);
      }
      if (req.body?.body_es !== undefined) {
        const bodyEs = decodeLiteralUnicodeEscapes(
          String(req.body.body_es || ""),
        ).trim();
        sets.push("body_es = ?");
        args.push(bodyEs || null);
      }
      for (const k of ["subject_en", "subject_es"] as const) {
        if (req.body?.[k] !== undefined) {
          sets.push(`${k} = ?`);
          args.push(String(req.body[k] || "").trim().slice(0, 300) || null);
        }
      }
      if (req.body?.category !== undefined) {
        if (
          !CONVERSATION_TEMPLATE_CATEGORIES.includes(String(req.body.category))
        ) {
          throw new HttpError(400, "validation.invalidField");
        }
        sets.push("category = ?");
        args.push(String(req.body.category));
      }
      if (req.body?.is_active !== undefined) {
        sets.push("is_active = ?");
        args.push(
          req.body.is_active === true ||
            req.body.is_active === 1 ||
            req.body.is_active === "1"
            ? 1
            : 0,
        );
      }
      if (req.body?.sort_order !== undefined) {
        sets.push("sort_order = ?");
        args.push(Number(req.body.sort_order) || 0);
      }
      if (!sets.length) throw new HttpError(400, "validation.invalidField");
      args.push(id);
      await pool.query(
        `UPDATE conversation_templates SET ${sets.join(", ")} WHERE id = ?`,
        args,
      );
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM conversation_templates WHERE id = ? LIMIT 1`,
        [id],
      );
      res.json({ template: mapConversationTemplateRow(rows[0]) });
    }),
  );

